{
  "code": "export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const log = [];
  const wait = (ms) => new Promise(r => setTimeout(r, ms));

  try {
    await page.setViewport({ width: 1280, height: 800 });
    log.push('Fazendo login...');
    await page.goto('https://app.cotadorsimplificado.com.br/login', { waitUntil: 'networkidle2', timeout: 60000 });
    await wait(2000);

    const emailInput = await page.$('#email_principal');
    if (emailInput) {
      await emailInput.click();
      await emailInput.type(EMAIL, { delay: 30 });
    }
    await wait(1000);

    let buttons = await page.$$('button');
    for (const btn of buttons) {
      const text = await page.evaluate(el => el.textContent, btn);
      if (text && text.includes('Continuar com Email')) {
        await btn.click();
        break;
      }
    }
    await wait(2000);

    await page.waitForSelector('#pwdInput', { timeout: 15000 });
    const senhaInput = await page.$('#pwdInput');
    if (senhaInput) {
      await senhaInput.click();
      await senhaInput.type(SENHA, { delay: 30 });
    }
    await wait(1000);

    buttons = await page.$$('button');
    for (const btn of buttons) {
      const text = await page.evaluate(el => el.textContent.trim(), btn);
      if (text === 'Entrar') {
        await btn.click();
        break;
      }
    }
    await wait(6000);
    log.push('Login OK');

    log.push('Clicando Hapvida...');
    const hapvidaImg = await page.$('img[src*=\"hapvida\"]');
    if (hapvidaImg) {
      const parent = await hapvidaImg.evaluateHandle(el => el.closest('.clickable-element') || el.parentElement.parentElement);
      await parent.click();
      await wait(3000);
    }
    log.push('Hapvida OK');

    const cookies = await page.cookies();
    const localStorage = await page.evaluate(() => {
      const items = {};
      for (let i = 0; i < window.localStorage.length; i++) {
        const key = window.localStorage.key(i);
        items[key] = window.localStorage.getItem(key);
      }
      return items;
    });

    return { success: true, log, url: page.url(), cookies, localStorage };
  } catch (error) {
    return { success: false, error: error.message, log };
  }
}"
}

