// SALVA SESSAO NO STATIC DATA
const staticData = $getWorkflowStaticData('global');
const input = $input.first().json;

if (input.success && input.cookies && input.cookies.length > 0) {
  staticData.cookies = input.cookies;
  staticData.localStorage = input.localStorage;
  staticData.ultimoLogin = new Date().toISOString();
  staticData.url = input.url;
}

const log = (input.log || []).join('\n');
const texto = `*LOGIN HAPVIDA*\n\nStatus: ${input.success ? 'SUCESSO' : 'ERRO'}\nErro: ${input.error || 'Nenhum'}\n\nLog:\n${log}\n\nSessao salva: ${input.success ? 'SIM - Agora execute o workflow 2!' : 'NAO'}`;

return [{ json: { number: '5583999471031', text: texto } }];
